addLab('inference','Confidence Interval Lab','METHODS · SPECIALIST',()=>{let intervals=[],key='';controls(pair(input('mu','Population mean μ',50,-1000,1000),input('sigma','Known population σ',10,.01,1000))+input('sampleN','Sample size',25,1,1000,1)+select('confidence','Confidence level',[['.95','95%'],['.90','90%'],['.99','99%']])+`<div class="actions">${btn('sample1','Take a sample')}${btn('sample100','Take 100 samples')}${btn('clearCI','Clear intervals')}</div>`+check('showMu','Show population mean',true));function sample(n){const mu=value('mu'),sd=value('sigma'),N=value('sampleN'),z={'.95':1.95996398454,'.90':1.64485362695,'.99':2.57582930355}[$('confidence').value];for(let i=0;i<n;i++){const mean=mu+sd/Math.sqrt(N)*normalRandom(),margin=z*sd/Math.sqrt(N);intervals.push({mean,lo:mean-margin,hi:mean+margin,hit:Math.abs(mean-mu)<=margin})}if(intervals.length>10000)intervals=intervals.slice(-10000);run()}$('sample1').onclick=()=>{try{sample(1)}catch(e){$('error').textContent=e.message}};$('sample100').onclick=()=>{try{sample(100)}catch(e){$('error').textContent=e.message}};$('clearCI').onclick=()=>{intervals=[];run()};update=()=>{const mu=value('mu'),sd=value('sigma'),n=value('sampleN'),k=[mu,sd,n,$('confidence').value].join(',');if(k!==key){intervals=[];key=k}const visible=intervals.slice(-60),range=4.5*sd/Math.sqrt(n),g=chart(mu-range,mu+range,0,Math.max(1,visible.length),'Population mean estimate','Sample',false,{y:[]});let s=g.s;if($('showMu').checked&&revealed())s+=line(g,[mu,0],[mu,Math.max(1,visible.length)],C.gold,'5 4');visible.forEach((v,i)=>{const col=revealed()?(v.hit?C.teal:C.red):C.purple;s+=line(g,[v.lo,i+.5],[v.hi,i+.5],col)+point(g,v.mean,i+.5,col,3)});svg(s,'Repeated confidence intervals with missed population means highlighted');formula('Sample mean ± z × σ / √n');const hits=intervals.filter(i=>i.hit).length;results([['Samples',intervals.length],['Intervals containing μ',hits],['Observed coverage',intervals.length?fmt(hits/intervals.length*100,1)+'%':'—']]);table(['Sample','Mean','Lower','Upper','Contains μ'],intervals.map((v,i)=>[i+1,v.mean,v.lo,v.hi,v.hit?'Yes':'No']));note('Samples come from a normal population with known σ. Sample means are drawn directly from their exact normal sampling distribution. The chart shows the latest 60 intervals; the table retains up to 10,000. Confidence describes long-run coverage, not the probability of a fixed μ moving within one interval.')}});
